        self.payload = payload
    }

    public func computeTransform(factor: Int, bias: Int) -> Int {
        let temp = (id * factor) + bias
        if temp > 1_000_000 {
            return (temp ^ 0x55AA) & 0xFFFF
        } else {
            return temp << 2
        }
    }

    public func processItems(_ items: [Int], predicate: (Int) -> Bool) -> Int {
        var sum: Int = 0
        for item in items where predicate(item) {
            sum += (item * 3) - 7
        }
        return sum + self.computeTransform(factor: 4, bias: 10)
    }
}

